# Pennsylvania Consolidated Statutes from palegis.us: each title's full HTML text (view-statute?txtType=HTM&iFrame=true), cut at the publisher's own section markers (<div class="Comment">18c301s</div> ... next marker).
import re
BASE = "https://www.palegis.us/statutes/consolidated"

def sections():
    _, idx = fetch(BASE)
    titles = []
    for t in re.findall(r"view-statute\?txtType=HTM&(?:amp;)?ttl=([0-9]+)", idx):
        if int(t) and t not in titles:          # ttl=0 is the Constitution, not a Pa.C.S. title
            titles.append(t)
    log(f"{len(titles)} titles")
    for t in titles:
        url = f"{BASE}/view-statute?txtType=HTM&ttl={t}&iFrame=true"
        try:
            _, html = fetch(url)
        except Exception as e:
            log(f"title {t} failed: {e}"); continue
        html = html.replace("\r", " ").replace("\n", " ")       # the source hard-wraps its lines; HTML whitespace is one space
        marks = list(re.finditer(r'<div class="Comment">\s*([0-9]+)c([0-9A-Za-z.\-]+?)s\s*</div>', html))
        allm = [m.start() for m in re.finditer(r'<div class="Comment">', html)]
        seen, n = set(), 0
        for m in marks:
            end = next((p for p in allm if p > m.start()), len(html))
            lines = block_text('<div id="law">' + html[m.end():end] + "</div>", id="law").split("\n")
            h = re.match(r"§+\s*([0-9][0-9A-Za-z.\-]*[0-9A-Za-z])\.\s*(.*)", lines[0]) if lines else None
            if not h:
                log(f"no section line at {t}c{m.group(2)}: {lines[:1]}"); continue
            sid, heading = h.group(1), h.group(2).strip().rstrip(".")
            text = "\n".join(lines[1:]).strip()
            if sid in seen:
                log(f"title {t} prints § {sid} twice; kept the first"); continue
            seen.add(sid)
            if not text and re.search(r"(?i)\((repealed|reserved|expired|deleted|suspended)", heading):
                text = heading                  # "§ 107. (Reserved)." is the whole section
            if text:
                n += 1
                yield {"id": sid, "heading": heading, "text": text, "url": f"{BASE}/view-statute?txtType=HTM&ttl={t}", "vars": {"ttl": str(int(t))}}
        log(f"title {t}: {n} sections")
